import { assetId, keysetId, mintOutputCommitment, mintTransactionId, outputId, policyDigest } from '../../../src/v2/identifiers.js';
import type { AssetDescriptor, MintNote, RSAKeyset } from '../../../src/v2/models.js';
import { V2ValidationError, validateAssetDescriptor, validateMintNote, validateRSAKeyset } from '../../../src/v2/validator.js';

const b = (value: number, length = 32) => new Uint8Array(length).fill(value);
const opaque = new Uint8Array([1]); const policy = { epoch_seconds: 3600, max_lifetime_epochs: 24, boundary: 'exclusive' as const }; const issuer = b(1); const domain = b(2); const modulus = b(3, 384); const owner = b(4); const nonce = b(5);
const descriptor: AssetDescriptor = { issuer, asset_code: 'FIX', unit: 'unit', decimals: 2, policy_digest: policyDigest(policy), expiry_policy: policy, asset_id: assetId({ issuer, asset_code: 'FIX', unit: 'unit', decimals: 2, policy_digest: policyDigest(policy), expiry_policy: policy }), issuer_signature: opaque };
const keyIdentity = { issuer_id: issuer, asset_id: descriptor.asset_id, spend_domain: domain, denomination: 10, issuance_epoch: 1, expiry_epoch: 2, modulus, public_exponent: 65537 as const, suite: 'RSABSSA-SHA384-PSS-Randomized' as const, authority_key_id: b(6) };
const keyset: RSAKeyset = { ...keyIdentity, keyset_id: keysetId(keyIdentity), authority_signature: opaque };
const payload = { keyset_id: keyset.keyset_id, asset_id: descriptor.asset_id, spend_domain: domain, denomination: 10, issuance_epoch: 1, expiry_epoch: 2, blinded_payload: { owner_material: owner, replay_nonce: nonce } };
const commitment = mintOutputCommitment(keyset.keyset_id, owner, nonce); const mintId = mintTransactionId(keyset.keyset_id, commitment);
const mint: MintNote = { kind: 'mint', asset_id: descriptor.asset_id, amount: 10, recipient_key: owner, spend_domain: domain, output_commitment: commitment, mint_transaction_id: mintId, output_index: 0, output_id: outputId(mintId, 0, commitment), issued_at: 3600, expires_at: 7200, keyset_id: keyset.keyset_id, mint_credential: { kind: 'mint', keyset_id: keyset.keyset_id, credential_payload: payload, signature_envelope: opaque } };
validateAssetDescriptor(descriptor); validateRSAKeyset(keyset, descriptor); validateMintNote(mint, descriptor, keyset, 3600); validateMintNote(mint, descriptor, keyset, 7199);
const expect = (mutate: () => void, check: () => void, category: string) => { mutate(); try { check(); throw new Error('accepted invalid Phase 1C value'); } catch (error) { if (!(error instanceof V2ValidationError) || error.category !== category) throw error; } };
expect(() => { descriptor.policy_digest = b(9); }, () => validateAssetDescriptor(descriptor), 'hash-binding'); descriptor.policy_digest = policyDigest(policy);
expect(() => { descriptor.asset_id = b(9); }, () => validateAssetDescriptor(descriptor), 'hash-binding'); descriptor.asset_id = assetId({ issuer, asset_code: 'FIX', unit: 'unit', decimals: 2, policy_digest: descriptor.policy_digest, expiry_policy: policy });
expect(() => { descriptor.expiry_policy.epoch_seconds = 0; }, () => validateAssetDescriptor(descriptor), 'schema'); descriptor.expiry_policy.epoch_seconds = 3600;
expect(() => { keyset.modulus = b(3, 383); }, () => validateRSAKeyset(keyset, descriptor), 'schema'); keyset.modulus = modulus;
expect(() => { keyset.public_exponent = 3 as 65537; }, () => validateRSAKeyset(keyset, descriptor), 'schema'); keyset.public_exponent = 65537;
expect(() => { keyset.suite = 'wrong' as RSAKeyset['suite']; }, () => validateRSAKeyset(keyset, descriptor), 'schema'); keyset.suite = 'RSABSSA-SHA384-PSS-Randomized';
expect(() => { keyset.denomination = 11; }, () => validateRSAKeyset(keyset, descriptor), 'hash-binding'); keyset.denomination = 10;
expect(() => { keyset.issuance_epoch = 2; }, () => validateRSAKeyset(keyset, descriptor), 'time'); keyset.issuance_epoch = 1;
expect(() => { keyset.asset_id = b(9); }, () => validateRSAKeyset(keyset, descriptor), 'provenance'); keyset.asset_id = descriptor.asset_id;
expect(() => { mint.recipient_key = b(8); }, () => validateMintNote(mint, descriptor, keyset), 'provenance'); mint.recipient_key = owner;
expect(() => { mint.amount = 11; }, () => validateMintNote(mint, descriptor, keyset), 'provenance'); mint.amount = 10;
expect(() => { mint.issued_at = 1; }, () => validateMintNote(mint, descriptor, keyset), 'time'); mint.issued_at = 3600;
expect(() => { mint.output_id = b(9); }, () => validateMintNote(mint, descriptor, keyset), 'hash-binding'); mint.output_id = outputId(mintId, 0, commitment);
expect(() => { mint.spend_domain = b(9); }, () => validateMintNote(mint, descriptor, keyset), 'provenance'); mint.spend_domain = domain;
expect(() => { mint.keyset_id = b(9); }, () => validateMintNote(mint, descriptor, keyset), 'provenance'); mint.keyset_id = keyset.keyset_id;
expect(() => { mint.mint_credential.keyset_id = b(9); }, () => validateMintNote(mint, descriptor, keyset), 'provenance'); mint.mint_credential.keyset_id = keyset.keyset_id;
try { validateMintNote(mint, descriptor, keyset, 7200); throw new Error('accepted exclusive expiry boundary'); } catch (error) { if (!(error instanceof V2ValidationError) || error.category !== 'time') throw error; }
console.log('V2 Phase 1C mint-binding tests: passed');
